package com.fitnutri.backend.records.workout;
import com.fitnutri.backend.activity.*;
import com.fitnutri.backend.activity.catalogue.*;
import com.fitnutri.backend.common.*;
import com.fitnutri.backend.profile.*;
import com.fitnutri.backend.records.*;
import com.fitnutri.backend.user.User;
import java.math.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class WorkoutEstimateTest {
 final Long owner=42L;final LocalDate date=LocalDate.of(2020,1,2);final UUID root=UUID.randomUUID(),strengthId=UUID.randomUUID(),cardioId=UUID.randomUUID();
 ExerciseOptionRepository options;MovementCatalogueRepository movements;ProfileService profiles;WeightEntryRepository weights;RecordDatePolicy dates;WorkoutEstimateService service;ExerciseOption strength,cardio,unavailable;
 @BeforeEach void setup(){options=mock(ExerciseOptionRepository.class);movements=mock(MovementCatalogueRepository.class);profiles=mock(ProfileService.class);weights=mock(WeightEntryRepository.class);dates=new RecordDatePolicy(Clock.fixed(Instant.parse("2026-10-17T01:00:00Z"),ZoneOffset.UTC),new ZoneResolver("Australia/Sydney"));var profile=new UserProfile();profile.setBirthYear(1990);when(profiles.requireCompletedAdultSetup(owner)).thenReturn(profile);var user=new User();user.setId(owner);var weight=WeightEntry.of(user,new BigDecimal("70"),LocalDate.of(2020,1,1));when(weights.findFirstByUserIdAndEntryDateLessThanEqualOrderByEntryDateDesc(eq(owner),any())).thenReturn(Optional.of(weight));strength=option(201L,"STRENGTH",type(101L,"3.5"));cardio=option(202L,"ACTIVITY",type(102L,"5"));cardio.setAllowedDetails(List.of("speedKmh","inclinePercent"));unavailable=option(203L,"ACTIVITY",null);when(options.findAllWithReferenceById(anyCollection())).thenReturn(List.of(strength,cardio,unavailable));var move=new MovementCatalogue();move.setId(301L);move.setActive(true);move.setReviewStatus("REVIEWED");move.setDefaultPeriodOption(strength);move.setAllowedFields(List.of("setCount","repetitions","loadKg"));move.setLoadBasis("TOTAL_BARBELL");when(movements.findAllWithDefaultById(anyCollection())).thenReturn(List.of(move));service=create(new ExerciseEstimateService(new ExerciseCatalog(mock(ExerciseTypeRepository.class)),profiles,weights,dates));}
 WorkoutEstimateService create(ExerciseEstimateService estimates){return new WorkoutEstimateService(options,movements,estimates,profiles,dates,new EquipmentDetailsValidator(),new CanonicalV2Json(new tools.jackson.databind.ObjectMapper()),mock(JdbcTemplate.class));}
 ExerciseOption option(long id,String kind,ExerciseType type){var row=new ExerciseOption();row.setId(id);row.setOptionKey("synthetic-"+id);row.setRevision("synthetic-only");row.setActive(true);row.setCategory(kind.equals("STRENGTH")?"STRENGTH":"CARDIO");row.setPeriodKind(kind);row.setDisplayName("Synthetic option");row.setReviewStatus("REVIEWED");row.setReference(type);row.setMappingKind(type==null?"UNAVAILABLE":"GENERAL_ACTIVITY_ESTIMATE");row.setMappingEvidence(Map.of("reason","Synthetic reviewed test reason"));return row;}
 ExerciseType type(long id,String met){var d=new ActivityDataset();d.setId(1L);d.setName("SYNTHETIC_WORKOUT_TEST_ONLY");d.setRelease("test");d.setRevision("synthetic");d.setVerified(true);d.setContentSha256("a".repeat(64));d.setSourceNote("Synthetic coefficient, not official data");d.setMinAge(19);d.setMaxAge(59);var t=new ExerciseType();t.setId(id);t.setDataset(d);t.setActivityKey("synthetic-"+id);t.setDisplayName("Synthetic reference");t.setSourceActivityCode("99901");t.setSourceDescription("Explicit synthetic calculation fixture");t.setMetValue(new BigDecimal(met));t.setActive(true);return t;}
 ExerciseEntryInputs.PreviewPeriod period(UUID id,String kind,String option,String minutes,Map<String,Object> details,List<ExerciseEntryInputs.Movement> moves){return new ExerciseEntryInputs.PreviewPeriod(id,kind,option,new BigDecimal(minutes),details,moves);}
 ExerciseEntryInputs.PreviewRequest request(ExerciseEntryInputs.PreviewEntry entry){return new ExerciseEntryInputs.PreviewRequest(date,"Australia/Sydney",RecordSource.MANUAL,entry);}
 @Test void independentSeventyMinuteExampleCountsStrengthOnceAndDetailsDoNotChangeEnergy(){var s=period(strengthId,"STRENGTH","201","50",Map.of(),List.of());var c=period(cardioId,"ACTIVITY","202","20",Map.of(),List.of());var first=service.previewNew(owner,request(new ExerciseEntryInputs.WorkoutPreview(root,"Synthetic workout",List.of(s,c),null)));assertEquals(new BigDecimal("70"),first.totalMinutes());assertEquals(new BigDecimal("854.233"),first.periods().getFirst().estimatedKj());assertEquals(new BigDecimal("488.133"),first.periods().get(1).estimatedKj());assertEquals(new BigDecimal("1342.366"),first.knownEnergyKj());var move=new ExerciseEntryInputs.Movement("301",3L,8L,new BigDecimal("40"));var withMoves=period(strengthId,"STRENGTH","201","50",Map.of(),List.of(move,move,move));var detailed=period(cardioId,"ACTIVITY","202","20",Map.of("speedKmh",new BigDecimal("5"),"inclinePercent",new BigDecimal("8")),List.of());var second=service.previewNew(owner,request(new ExerciseEntryInputs.WorkoutPreview(root,"Renamed",List.of(withMoves,detailed),null)));assertEquals(first.fingerprint(),second.fingerprint());assertEquals(first.knownEnergyKj(),second.knownEnergyKj());assertNotEquals(first.inputSignature(),second.inputSignature());}
 @Test void partialAndAllUnavailableNeverFabricateZeroEnergy(){var s=period(strengthId,"STRENGTH","201","50",Map.of(),List.of());var none=period(cardioId,"ACTIVITY","203","20",Map.of(),List.of());var mixed=service.previewNew(owner,request(new ExerciseEntryInputs.WorkoutPreview(root,null,List.of(s,none),null)));assertTrue(mixed.partial());assertEquals(new BigDecimal("854.233"),mixed.knownEnergyKj());assertEquals("NO_APPLICABLE_REFERENCE",mixed.periods().get(1).status());assertNotNull(mixed.periods().get(1).unavailableReason());var all=service.previewNew(owner,request(new ExerciseEntryInputs.QuickPreview(cardioId,none)));assertNull(all.knownEnergyKj());assertFalse(all.partial());assertNull(all.periods().getFirst().estimatedKj());}
 @Test void missingDatedWeightIsExplicitAndBadReferenceOrWrongMovementCannotBecomeUnavailable(){when(weights.findFirstByUserIdAndEntryDateLessThanEqualOrderByEntryDateDesc(eq(owner),any())).thenReturn(Optional.empty());var s=period(strengthId,"STRENGTH","201","50",Map.of(),List.of());assertEquals("NO_WEIGHT",service.previewNew(owner,request(new ExerciseEntryInputs.QuickPreview(strengthId,s))).periods().getFirst().status());var wrong=period(cardioId,"ACTIVITY","202","20",Map.of(),List.of(new ExerciseEntryInputs.Movement("301",null,null,null)));assertThrows(BusinessException.class,()->service.previewNew(owner,request(new ExerciseEntryInputs.QuickPreview(cardioId,wrong))));strength.setReference(null);assertThrows(BusinessException.class,()->service.previewNew(owner,request(new ExerciseEntryInputs.QuickPreview(strengthId,s))));}
 @Test void incompatibleDetailsInactiveOptionsAndServiceFailureAreRejected(){var bad=period(strengthId,"STRENGTH","201","50",Map.of("speedKmh",new BigDecimal("5")),List.of());assertThrows(BusinessException.class,()->service.previewNew(owner,request(new ExerciseEntryInputs.QuickPreview(strengthId,bad))));var s=period(strengthId,"STRENGTH","201","50",Map.of(),List.of());strength.setActive(false);assertEquals("REFERENCE_INACTIVE",assertThrows(BusinessException.class,()->service.previewNew(owner,request(new ExerciseEntryInputs.QuickPreview(strengthId,s)))).code());strength.setActive(true);var broken=mock(ExerciseEstimateService.class);when(broken.estimateLocked(anyLong(),any(),any(),any(),anyString())).thenThrow(new org.springframework.dao.DataAccessResourceFailureException("private database failure"));assertThrows(BusinessException.class,()->create(broken).previewNew(owner,request(new ExerciseEntryInputs.QuickPreview(strengthId,s))));}
 @Test void badMinutesAreLocatedByPeriodUuidAndUnfilledKnownDetailsStayAbsent(){for(String minutes:List.of("0","-1","1440.01","0.001")){var p=period(strengthId,"STRENGTH","201",minutes,Map.of(),List.of());var error=assertThrows(BusinessException.class,()->service.previewNew(owner,request(new ExerciseEntryInputs.QuickPreview(strengthId,p))));assertEquals(strengthId.toString(),error.fields().getFirst().clientEntryId());}var empty=new LinkedHashMap<String,Object>();empty.put("speedKmh",null);assertTrue(new EquipmentDetailsValidator().normalise(strength,empty).isEmpty());for(Object value:List.of("5",true,Double.NaN,new BigDecimal("100.01"))){var p=period(cardioId,"ACTIVITY","202","20",Map.of("speedKmh",value),List.of());assertThrows(BusinessException.class,()->service.previewNew(owner,request(new ExerciseEntryInputs.QuickPreview(cardioId,p))));}}
}
